import { createServer, IncomingMessage } from "node:http";
import { Entity as EntityV1 } from "../../generated/ts/v1/entity";
import { Entity as EntityV2 } from "../../generated/ts/v2/entity";

const observationsHeader = "X-Schema-Sentinel-Observations";
const traceHeader = "X-Service-Trace";

export function processEntity(rawBytes: Uint8Array, version: string) {
  if (version !== "v1" && version !== "v2") throw new Error(`Unsupported schema version: ${version}`);
  const entity = version === "v1" ? EntityV1.decode(rawBytes) : EntityV2.decode(rawBytes);
  const fields = { entity_id: entity.entityId, ...(version === "v1" ? { name: (entity as EntityV1).name } : {}) };
  console.log(JSON.stringify({ runtime: "typescript", version, fields }));
  return { entity, fields };
}

async function readBody(request: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks);
}

if (process.argv.includes("--serve")) {
  createServer(async (request, response) => {
    if (request.method === "GET" && request.url === "/health") {
      response.writeHead(200, { "content-type": "application/json" });
      response.end(JSON.stringify({ status: "ok", runtime: "typescript" }));
      return;
    }
    if (request.method !== "POST" || request.url !== "/relay") {
      response.writeHead(404); response.end(); return;
    }
    try {
      const { entity, fields } = processEntity(await readBody(request), "v1");
      const trace = JSON.parse(String(request.headers[traceHeader.toLowerCase()] ?? "[]"));
      trace.push("typescript");
      const downstream = await fetch(process.env.CSHARP_RELAY_URL ?? "http://localhost:8002/relay", {
        method: "POST",
        headers: { "content-type": "application/x-protobuf", [traceHeader]: JSON.stringify(trace) },
        body: Buffer.from(EntityV1.encode(entity as EntityV1).finish()),
        signal: AbortSignal.timeout(5000),
      });
      if (!downstream.ok) throw new Error(`C# relay returned ${downstream.status}`);
      const body = Buffer.from(await downstream.arrayBuffer());
      const observations = [{ runtime: "typescript", fields }, ...JSON.parse(downstream.headers.get(observationsHeader) ?? "null")];
      response.writeHead(200, {
        "content-type": "application/x-protobuf", "content-length": body.length,
        [observationsHeader]: JSON.stringify(observations).replace(/[\u007f-\uffff]/g, c => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`),
        [traceHeader]: downstream.headers.get(traceHeader) ?? "[]",
      });
      response.end(body);
    } catch (error) {
      response.writeHead(400, { "content-type": "application/json" });
      response.end(JSON.stringify({ error: String(error) }));
    }
  }).listen(Number(process.env.PORT ?? "8001"), "0.0.0.0");
} else {
  const version = process.argv.includes("--v2") ? "v2" : "v1";
  const bytes = version === "v1"
    ? EntityV1.encode({ entityId: "ts_303", name: "Sensor C" }).finish()
    : EntityV2.encode({ entityId: "ts_303" }).finish();
  processEntity(bytes, version);
}

using System.Text.Json;
using Google.Protobuf;

const string observationsHeader = "X-Schema-Sentinel-Observations";
const string traceHeader = "X-Service-Trace";

static (IMessage Entity, Dictionary<string, string> Fields) ProcessEntity(byte[] rawBytes, string version)
{
    IMessage entity;
    Dictionary<string, string> fields;
    if (version == "v1")
    {
        var decoded = Simulation.V1.Entity.Parser.ParseFrom(rawBytes);
        entity = decoded;
        fields = new() { ["entity_id"] = decoded.EntityId, ["name"] = decoded.Name };
    }
    else if (version == "v2")
    {
        var decoded = Simulation.V2.Entity.Parser.ParseFrom(rawBytes);
        entity = decoded;
        fields = new() { ["entity_id"] = decoded.EntityId };
    }
    else throw new ArgumentException($"Unsupported version: {version}");
    Console.WriteLine(JsonSerializer.Serialize(new { runtime = "csharp", version, fields }));
    return (entity, fields);
}

if (args.Contains("--healthcheck"))
{
    using var client = new HttpClient { Timeout = TimeSpan.FromSeconds(1) };
    try { return (await client.GetAsync("http://localhost:8002/health")).IsSuccessStatusCode ? 0 : 1; }
    catch (Exception error) when (error is HttpRequestException or TaskCanceledException) { return 1; }
}
if (!args.Contains("--serve"))
{
    var version = args.Contains("--v2") ? "v2" : "v1";
    IMessage entity = version == "v1"
        ? new Simulation.V1.Entity { EntityId = "cs_202", Name = "Sensor B" }
        : new Simulation.V2.Entity { EntityId = "cs_202" };
    ProcessEntity(entity.ToByteArray(), version);
    return 0;
}
var builder = WebApplication.CreateBuilder(args.Where(arg => arg != "--serve").ToArray());
var app = builder.Build();
app.MapGet("/health", () => Results.Json(new { status = "ok", runtime = "csharp" }));
app.MapPost("/relay", async (HttpRequest request, HttpResponse response) =>
{
    try
    {
        using var body = new MemoryStream();
        await request.Body.CopyToAsync(body);
        var (entity, fields) = ProcessEntity(body.ToArray(), "v1");
        var trace = JsonSerializer.Deserialize<List<string>>(request.Headers[traceHeader].FirstOrDefault() ?? "[]")
            ?? throw new JsonException("Trace must be an array");
        trace.Add("csharp");
        response.Headers[observationsHeader] = JsonSerializer.Serialize(new[] { new { runtime = "csharp", fields } });
        response.Headers[traceHeader] = JsonSerializer.Serialize(trace);
        response.ContentType = "application/x-protobuf";
        await response.Body.WriteAsync(entity.ToByteArray());
    }
    catch (Exception error) when (error is InvalidProtocolBufferException or JsonException)
    {
        response.StatusCode = 400;
        await response.WriteAsJsonAsync(new { error = error.Message });
    }
});
app.Run();
return 0;
